import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
const check = (input, expected) => assert.equal(slugify(input), expected, JSON.stringify(input));

if (mode === 'decomposition') {
  check('Crème Brûlée', 'creme-brulee');
  check('ÀÁÂÃÄÅ Ç ÈÉÊË ÌÍÎÏ Ñ ÒÓÔÕÖ ÙÚÛÜ ÝŸ', 'aaaaaa-c-eeee-iiii-n-ooooo-uuuu-yy');
  check('Việt Nam — Tiếng Việt', 'viet-nam-tieng-viet');
  // Exhaustively cover Latin letters whose canonical decomposition is an
  // ASCII letter plus one or more accents, rather than a selected language.
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{Script=Latin}$/u.test(letter) || !/^\p{L}$/u.test(letter)) continue;
    const decomposed = letter.normalize('NFD');
    if (/^[A-Za-z]\p{M}+$/u.test(decomposed)) {
      check(letter, decomposed[0].toLowerCase());
      check('X' + letter + 'Y', 'x' + decomposed[0].toLowerCase() + 'y');
    }
  }
} else if (mode === 'exceptions') {
  const pairs = [
    ['Łł', 'll'], ['Øø', 'oo'], ['Ææ', 'aeae'], ['Œœ', 'oeoe'],
    ['ẞß', 'ssss'], ['Đđ', 'dd'], ['Ðð', 'dd'], ['Þþ', 'thth'],
    ['Ħħ', 'hh'], ['Ŧŧ', 'tt'], ['ı', 'i'], ['Ŋŋ', 'nn'],
    ['ſ', 's'], ['Ĳĳ', 'ijij'], ['ﬀﬁﬂﬃﬄﬅﬆ', 'fffiflffifflstst'],
    ['ǼǽǢǣ', 'aeaeaeae'], ['Ǿǿ', 'oo'],
  ];
  check('Łódź', 'lodz');
  check('smørrebrød Straße Æsir Œuvre', 'smorrebrod-strasse-aesir-oeuvre');
  for (const [input, expected] of pairs) {
    check(input, expected);
    check('A' + input + 'Z', 'a' + expected + 'z');
    check('  ' + input + ' / ' + input + '  ', expected + '-' + expected);
  }
} else if (mode === 'combining') {
  const pairs = [
    ['Cre\u0300me Bru\u0302le\u0301e', 'creme-brulee'],
    ['Cafe\u0301', 'cafe'], ['a\u0308b', 'ab'],
    ['A\u030a\u0301 B\u0323\u0307 C\u0327', 'a-b-c'],
    ['İstanbul', 'istanbul'], ['I\u0307stanbul', 'istanbul'],
    ['Ł\u0301o\u0301dz\u0301', 'lodz'], ['æ\u0301 ß\u0308', 'ae-ss'],
    ['e\u0301 / e\u0301', 'e-e'], ['é\u0323cole', 'ecole'],
  ];
  for (const [input, expected] of pairs) check(input, expected);
  for (const input of ['Crème Brûlée', 'Ångström', 'Việt Nam', 'Ǽsir', 'İstanbul']) {
    const expected = { 'Crème Brûlée': 'creme-brulee', 'Ångström': 'angstrom', 'Việt Nam': 'viet-nam', 'Ǽsir': 'aesir', 'İstanbul': 'istanbul' }[input];
    check(input.normalize('NFD'), expected);
    check(input.normalize('NFC'), expected);
  }
} else if (mode === 'regression') {
  for (const [input, expected] of [
    ['Hello, World!', 'hello-world'], ['  --Release 2.0--  ', 'release-2-0'],
    ['', ''], [' ---!? 🐱 ', ''], ['a__b...c\nd\te', 'a-b-c-d-e'],
    ['ABC 0123456789', 'abc-0123456789'], ['fooBar', 'foobar'],
    ['Привет мир', 'привет-мир'], ['Ёж ЙОД', 'ёж-йод'],
    ['Αθήνα Ώρα', 'αθήνα-ώρα'], ['日本語 東京', '日本語-東京'],
    ['한글 한국', '한글-한국'], ['中文', '中文'], ['ԱԲԳ', 'աբգ'],
  ]) {
    check(input, expected);
  }
  // All non-Latin Unicode letters must retain their spelling (after casing).
  // Batches keep assertion diagnostics and memory bounded.
  let batch = [];
  const flush = () => {
    if (batch.length) check(batch.join(' '), batch.join('-').toLowerCase());
    batch = [];
  };
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const c = String.fromCodePoint(cp);
    if (/^\p{L}$/u.test(c) && !/^\p{Script=Latin}$/u.test(c)) {
      batch.push(c);
      if (batch.length === 512) flush();
    }
  }
  flush();
} else if (mode === 'mixed') {
  check('Crème 東京 Łódź Αθήνα Ёж', 'creme-東京-lodz-αθήνα-ёж');
  check('Øresund 日本語 Straße 한글', 'oresund-日本語-strasse-한글');
} else {
  throw new Error('Unknown check group: ' + mode);
}
